/**
 * 候选图片预处理节点 (v2.0)
 * 根据FR-03要求对Pexels API返回的图片进行预处理
 */

// 可配置参数
const MIN_WIDTH = 1200; // 最小宽度要求
const PER_PAGE = 8; // 每页结果数

/**
 * 筛选符合条件的图片并提取URL列表
 * @param {Array} photos - Pexels API返回的图片数组
 * @returns {Object} 包含筛选后的图片数组和URL列表
 */
function preprocessPhotos(photos) {
  // FR-03.1: 过滤掉宽度小于1200px的图片
  const filteredPhotos = photos.filter(photo => {
    return photo.width >= MIN_WIDTH && photo.src && photo.src.original;
  });

  // FR-03.2: 提取候选图片URL列表
  const candidateUrls = filteredPhotos.map(photo => photo.src.original);

  return {
    filteredPhotos,
    candidateUrls,
    originalPhotos: photos
  };
}

// 主处理逻辑
try {
  const inputData = $input.all();

  // 检查是否有输入数据
  if (!inputData || inputData.length === 0) {
    return [{
      json: {
        error: "No input data received.",
        candidateUrls: [],
        filteredPhotos: [],
        originalPhotos: [],
        originalInput: null
      }
    }];
  }

  const firstInput = inputData[0];
  const apiResponse = firstInput.json;

  // 保存原始输入数据（包含articleTitle）
  const originalInput = $('Start').first().json;

  // 检查API响应格式
  if (!apiResponse || !apiResponse.photos) {
    return [{
      json: {
        error: "Invalid API response format.",
        candidateUrls: [],
        filteredPhotos: [],
        originalPhotos: [],
        originalInput
      }
    }];
  }

  const photos = apiResponse.photos;

  // 执行图片预处理
  const result = preprocessPhotos(photos);

  // FR-03.3: 检查是否有候选图片
  if (result.candidateUrls.length === 0) {
    return [{
      json: {
        error: "No suitable images found after filtering.",
        candidateUrls: [],
        filteredPhotos: [],
        originalPhotos: photos,
        originalInput
      }
    }];
  }

  // 返回预处理结果
  return [{
    json: {
      error: null,
      candidateUrls: result.candidateUrls,
      filteredPhotos: result.filteredPhotos,
      originalPhotos: result.originalPhotos,
      originalInput
    }
  }];

} catch (error) {
  // 处理意外错误
  return [{
    json: {
      error: `Processing error: ${error.message}`,
      candidateUrls: [],
      filteredPhotos: [],
      originalPhotos: [],
      originalInput: null
    }
  }];
}

