/**
 * 最终选择与格式化节点 (v2.0)
 * 根据AI选择结果或备用逻辑选择最终图片并格式化输出
 */

/**
 * 格式化最终输出结果
 * @param {Object|null} selectedPhoto - 选中的图片对象
 * @param {string|null} errorMessage - 错误信息
 * @returns {Object} 格式化的输出对象
 */
function formatOutput(selectedPhoto, errorMessage = null) {
  if (errorMessage) {
    return {
      imageUrl: null,
      altText: null,
      photographer: null,
      photographerUrl: null,
      error: errorMessage
    };
  }

  if (!selectedPhoto) {
    return {
      imageUrl: null,
      altText: null,
      photographer: null,
      photographerUrl: null,
      error: "No images found for the given keywords."
    };
  }

  return {
    imageUrl: selectedPhoto.src.original,
    altText: selectedPhoto.alt || "",
    photographer: selectedPhoto.photographer || "",
    photographerUrl: selectedPhoto.photographer_url || "",
    error: null
  };
}

/**
 * 解析AI响应并提取bestImageIndex
 * @param {Object} aiResponse - AI API响应
 * @returns {number|null} 图片索引或null
 */
function parseAiResponse(aiResponse) {
  try {
    // 尝试从不同可能的响应格式中提取文本
    let responseText = '';

    if (aiResponse.candidates && aiResponse.candidates[0] && aiResponse.candidates[0].content) {
      responseText = aiResponse.candidates[0].content.parts[0].text;
    } else if (aiResponse.text) {
      responseText = aiResponse.text;
    } else if (typeof aiResponse === 'string') {
      responseText = aiResponse;
    }

    // 尝试解析JSON
    const jsonMatch = responseText.match(/\{[^}]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      return parsed.bestImageIndex;
    }

    return null;
  } catch (error) {
    return null;
  }
}

// 主处理逻辑
try {
  const inputData = $input.all();

  if (!inputData || inputData.length === 0) {
    return [formatOutput(null, "No input data received.")];
  }

  const preprocessData = inputData[0].json;
  const aiData = inputData[1] ? inputData[1].json : null;

  // 检查预处理是否有错误
  if (preprocessData.error) {
    return [formatOutput(null, preprocessData.error)];
  }

  const filteredPhotos = preprocessData.filteredPhotos;
  const originalPhotos = preprocessData.originalPhotos;

  if (!filteredPhotos || filteredPhotos.length === 0) {
    return [formatOutput(null, "No suitable images found after filtering.")];
  }

  let selectedPhoto = null;

  // FR-05.1: 尝试使用AI选择结果
  if (aiData && !aiData.error) {
    const bestIndex = parseAiResponse(aiData);
    if (bestIndex !== null && bestIndex >= 0 && bestIndex < filteredPhotos.length) {
      selectedPhoto = filteredPhotos[bestIndex];
    }
  }

  // FR-05.2: 备用逻辑 - 选择第一张筛选后的图片
  if (!selectedPhoto) {
    selectedPhoto = filteredPhotos[0];
  }

  return [formatOutput(selectedPhoto)];

} catch (error) {
  return [formatOutput(null, `Processing error: ${error.message}`)];
}

/**
 * Pexels API错误处理节点
 * 处理Pexels API请求失败的情况
 */

// 获取错误信息
const errorData = $input.all()[0];
const error = errorData.error;

let errorMessage = "Unknown error occurred.";

// 根据HTTP状态码确定错误类型
if (error && error.httpCode) {
  switch (error.httpCode) {
    case 401:
      // EH-01: API认证失败
      errorMessage = "API authentication failed. Please check your Pexels API credentials.";
      break;
    case 429:
      errorMessage = "API rate limit exceeded. Please try again later.";
      break;
    case 500:
    case 502:
    case 503:
    case 504:
      // EH-03: API服务不可用
      errorMessage = "Pexels API service is currently unavailable. Please try again later.";
      break;
    default:
      errorMessage = `API request failed with status ${error.httpCode}: ${error.message || 'Unknown error'}`;
  }
} else if (error && error.message) {
  errorMessage = error.message;
}

// 返回错误格式的输出
return [{
  json: {
    imageUrl: null,
    altText: null,
    photographer: null,
    photographerUrl: null,
    error: errorMessage
  }
}];

/**
 * AI错误处理节点
 * 处理多模态AI API调用失败的情况
 */

// 获取预处理数据和错误信息
const inputData = $input.all();
const preprocessData = inputData[0].json;
const errorData = inputData[1];
const error = errorData.error;

let errorMessage = "AI API call failed.";

// 根据HTTP状态码确定错误类型
if (error && error.httpCode) {
  switch (error.httpCode) {
    case 401:
      // EH-04: AI API认证失败
      errorMessage = "AI API authentication failed. Please check your Google AI API credentials.";
      break;
    case 429:
      errorMessage = "AI API rate limit exceeded. Please try again later.";
      break;
    case 500:
    case 502:
    case 503:
    case 504:
      // EH-04: AI API服务不可用
      errorMessage = "AI API service is currently unavailable. Using fallback logic.";
      break;
    default:
      errorMessage = `AI API request failed with status ${error.httpCode}: ${error.message || 'Unknown error'}. Using fallback logic.`;
  }
} else if (error && error.message) {
  errorMessage = `AI API error: ${error.message}. Using fallback logic.`;
}

// FR-05.2: 触发备用逻辑 - 选择第一张筛选后的图片
if (preprocessData && preprocessData.filteredPhotos && preprocessData.filteredPhotos.length > 0) {
  const selectedPhoto = preprocessData.filteredPhotos[0];
  return [{
    json: {
      imageUrl: selectedPhoto.src.original,
      altText: selectedPhoto.alt || "",
      photographer: selectedPhoto.photographer || "",
      photographerUrl: selectedPhoto.photographer_url || "",
      error: null
    }
  }];
} else {
  // 如果连预处理都失败了
  return [{
    json: {
      imageUrl: null,
      altText: null,
      photographer: null,
      photographerUrl: null,
      error: errorMessage
    }
  }];
}
